/**
 * @fileoverview RSA in `keyformat`: PKCS#1 `RSAPublicKey` / `RSAPrivateKey`
 * (RFC 8017 A.1), SPKI and PKCS#8 (rsaEncryption, NULL parameters). Oracle:
 * keys generated by `node:crypto` — fw's encodings are byte-identical to
 * node's DER (DER is canonical, so equal keys give equal bytes) and fw's
 * decodings equal node's JWK components; a key decoded by fw signs with
 * `pkc/rsa` what node verifies.
 */

import { describe, test, expect } from 'bun:test';
import nodeCrypto from 'node:crypto';
import { keyformat } from './keyformat.js';
import { asn1 } from './asn1.js';
import { rsa } from '../pkc/rsa.js';
import { bitArray } from './bitArray.js';
import { bn } from './bn.js';
import { random } from './random.js';
import { aes } from '../cipher/aes.js';
import { sha256 } from '../hash/sha256.js';
import { utf8 } from '../../io/codec/utf8.js';

const K = keyformat.factory(asn1.factory());
const _ba = bitArray.factory();
const _sha256 = sha256.factory(_ba, utf8.factory());
const _rng = random.factory(_ba, aes.factory(), _sha256);
const R = rsa.factory(_ba, bn.factory(_ba, _rng), _rng);

const u8 = (b) => new Uint8Array(b.buffer, b.byteOffset, b.byteLength);
const b64u = (s) => u8(Buffer.from(s, 'base64url'));
const same = (a, b) => a instanceof Uint8Array && a.length === b.length && a.every((x, i) => x === b[i]);
const quiet = (fn) => { const w = console.warn; console.warn = () => {}; try { return fn(); } finally { console.warn = w; } };

/** A node-generated key pair, its four DER forms and its JWK components as fw key objects. */
function nodeKey(bits, e) {
    const { publicKey, privateKey } = nodeCrypto.generateKeyPairSync('rsa', { modulusLength: bits, publicExponent: e });
    const jwk = privateKey.export({ format: 'jwk' });
    return {
        node: { publicKey, privateKey },
        der: {
            spki: u8(publicKey.export({ type: 'spki', format: 'der' })),
            pkcs1Pub: u8(publicKey.export({ type: 'pkcs1', format: 'der' })),
            pkcs8: u8(privateKey.export({ type: 'pkcs8', format: 'der' })),
            pkcs1Priv: u8(privateKey.export({ type: 'pkcs1', format: 'der' })),
        },
        pub: { n: b64u(jwk.n), e: b64u(jwk.e) },
        priv: { n: b64u(jwk.n), e: b64u(jwk.e), d: b64u(jwk.d), p: b64u(jwk.p), q: b64u(jwk.q), dp: b64u(jwk.dp), dq: b64u(jwk.dq), qInv: b64u(jwk.qi) },
    };
}

const KEYS = [nodeKey(2048, 65537), nodeKey(3072, 3)];
const FIELDS = ['n', 'e', 'd', 'p', 'q', 'dp', 'dq', 'qInv'];

describe('keyformat RSA — against node:crypto', () => {
    for (const [i, k] of KEYS.entries()) {
        const label = i === 0 ? '2048 bits, e = 65537' : '3072 bits, e = 3';

        test(`${label}: encodings are byte-identical to node's DER`, () => {
            expect(same(K.encodeSpkiRsa(k.pub), k.der.spki)).toBe(true);
            expect(same(K.encodeRsaPublicKey(k.pub), k.der.pkcs1Pub)).toBe(true);
            expect(same(K.encodePkcs8Rsa(k.priv), k.der.pkcs8)).toBe(true);
            expect(same(K.encodeRsaPrivateKey(k.priv), k.der.pkcs1Priv)).toBe(true);
        });

        test(`${label}: decodings equal node's JWK components (unsigned)`, () => {
            for (const pub of [K.decodeSpkiRsa(k.der.spki), K.decodeRsaPublicKey(k.der.pkcs1Pub)]) {
                expect(same(pub.n, k.pub.n) && same(pub.e, k.pub.e)).toBe(true);
            }
            for (const priv of [K.decodePkcs8Rsa(k.der.pkcs8), K.decodeRsaPrivateKey(k.der.pkcs1Priv)]) {
                for (const f of FIELDS) expect([f, same(priv[f], k.priv[f])]).toEqual([f, true]);
            }
        });
    }

    test('a key decoded by fw signs (PSS) what node verifies', () => {
        const k = KEYS[0];
        const priv = K.decodePkcs8Rsa(k.der.pkcs8);
        const msg = new TextEncoder().encode('keyformat rsa');
        const sig = R.pssSign(priv, msg, _sha256, 32);
        expect(sig).not.toBe(false);
        const ok = nodeCrypto.verify('sha256', msg, { key: k.node.publicKey, padding: nodeCrypto.constants.RSA_PKCS1_PSS_PADDING, saltLength: 32 }, sig);
        expect(ok).toBe(true);
        expect(R.pssVerify(K.decodeSpkiRsa(k.der.spki), msg, sig, _sha256, 32)).toBe(true);
    });
});

describe('keyformat RSA — strict decoding', () => {
    const k = KEYS[0];
    const A = asn1.factory();

    test('an EC or Edwards SPKI is not an RSA key', () => {
        const ec = u8(nodeCrypto.generateKeyPairSync('ec', { namedCurve: 'P-256' }).publicKey.export({ type: 'spki', format: 'der' }));
        const ed = u8(nodeCrypto.generateKeyPairSync('ed25519').publicKey.export({ type: 'spki', format: 'der' }));
        expect(quiet(() => K.decodeSpkiRsa(ec))).toBe(false);
        expect(quiet(() => K.decodeSpkiRsa(ed))).toBe(false);
        const ecPriv = u8(nodeCrypto.generateKeyPairSync('ec', { namedCurve: 'P-256' }).privateKey.export({ type: 'pkcs8', format: 'der' }));
        expect(quiet(() => K.decodePkcs8Rsa(ecPriv))).toBe(false);
    });

    test('rsaEncryption without its NULL parameters is refused', () => {
        const noNull = A.encodeSequence([A.encodeSequence([A.encodeOid(K.OID.RSA)]), A.encodeBitString(k.der.pkcs1Pub, 0)]);
        expect(quiet(() => K.decodeSpkiRsa(noNull))).toBe(false);
    });

    test('a multi-prime (version 1) private key is refused', () => {
        const v1 = new Uint8Array(k.der.pkcs1Priv);
        // the version INTEGER right after the outer SEQUENCE header (30 82 LL LL 02 01 00)
        expect([v1[4], v1[5], v1[6]]).toEqual([0x02, 0x01, 0x00]);
        v1[6] = 0x01;
        expect(quiet(() => K.decodeRsaPrivateKey(v1))).toBe(false);
    });

    test('trailing bytes, truncation and garbage are refused', () => {
        const tail = new Uint8Array(k.der.spki.length + 1); tail.set(k.der.spki);
        expect(quiet(() => K.decodeSpkiRsa(tail))).toBe(false);
        expect(quiet(() => K.decodeSpkiRsa(k.der.spki.subarray(0, k.der.spki.length - 1)))).toBe(false);
        expect(quiet(() => K.decodeRsaPrivateKey(k.der.pkcs1Priv.subarray(0, 40)))).toBe(false);
        expect(quiet(() => K.decodeRsaPublicKey(new Uint8Array([0x30, 0x00])))).toBe(false);
        expect(quiet(() => K.decodePkcs8Rsa('not der'))).toBe(false);
    });

    test('encoding a private key without all eight integers is false', () => {
        const { qInv, ...partial } = KEYS[0].priv;
        expect(qInv).toBeInstanceOf(Uint8Array);
        expect(quiet(() => K.encodeRsaPrivateKey(partial))).toBe(false);
        expect(quiet(() => K.encodePkcs8Rsa(partial))).toBe(false);
        expect(quiet(() => K.encodeSpkiRsa({ n: KEYS[0].pub.n }))).toBe(false);
    });
});
